"""
Git Hooks Integration (pre-commit hook installation and verification).
"""

from __future__ import annotations
import os
import stat
import subprocess
from typing import Tuple, List

PRE_COMMIT_SCRIPT_TEMPLATE = """#!/usr/bin/env bash
# Auto-generated by Automated Code Reviewer & Complexity Profiler
# Runs AST checks, Big-O profiler, and edge-case tests on staged submission files.

set -e

# Focus on user code submissions, excluding tool internal engine, fixtures, and tests
STAGED_FILES=$(git diff --cached --name-only --diff-filter=ACM | grep -E '\\.(py|c|cpp|cc)$' | grep -v -E '^(codereview/|examples/|tests/|setup\\.py)' || true)

if [ -z "$STAGED_FILES" ]; then
    exit 0
fi

echo "======================================================================"
echo "🛡️  Running Automated Code Reviewer on staged submissions..."
echo "======================================================================"

EXIT_CODE=0

for FILE in $STAGED_FILES; do
    if [ -f "$FILE" ]; then
        echo "Inspecting: $FILE"
        python3 -m codereview.cli review "$FILE" --strict || EXIT_CODE=1
    fi
done

if [ $EXIT_CODE -ne 0 ]; then
    echo ""
    echo "❌ Commit rejected: One or more staged files failed edge-case testing or has critical issues."
    echo "💡 Fix the corner-case issues above, or bypass with 'git commit --no-verify'."
    exit 1
fi

echo "✅ All staged code submissions passed edge-case reviews and complexity checks."
exit 0
"""


def get_git_root(start_path: str = ".") -> Tuple[bool, str]:
    try:
        proc = subprocess.run(
            ["git", "rev-parse", "--show-toplevel"],
            cwd=start_path,
            capture_output=True,
            text=True,
        )
        if proc.returncode == 0:
            return True, proc.stdout.rstrip("\r\n")
    except Exception:
        pass
    return False, ""


def install_git_hook(repo_path: str = ".") -> Tuple[bool, str]:
    is_git, git_root = get_git_root(repo_path)
    if not is_git:
        return False, "Not inside a Git repository. Run 'git init' first."

    hooks_dir = os.path.join(git_root, ".git", "hooks")
    os.makedirs(hooks_dir, exist_ok=True)

    hook_file = os.path.join(hooks_dir, "pre-commit")

    if os.path.exists(hook_file):
        with open(hook_file, "r", encoding="utf-8", errors="ignore") as f:
            content = f.read()
        if "Automated Code Reviewer" not in content:
            backup_path = hook_file + ".backup"
            with open(backup_path, "w", encoding="utf-8") as f:
                f.write(content)

    with open(hook_file, "w", encoding="utf-8") as f:
        f.write(PRE_COMMIT_SCRIPT_TEMPLATE)

    current_stat = os.stat(hook_file)
    os.chmod(hook_file, current_stat.st_mode | stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)

    return True, f"Successfully installed pre-commit hook at {hook_file}"


def uninstall_git_hook(repo_path: str = ".") -> Tuple[bool, str]:
    is_git, git_root = get_git_root(repo_path)
    if not is_git:
        return False, "Not inside a Git repository."

    hook_file = os.path.join(git_root, ".git", "hooks", "pre-commit")
    if os.path.exists(hook_file):
        os.remove(hook_file)
        backup = hook_file + ".backup"
        if os.path.exists(backup):
            os.rename(backup, hook_file)
            return True, f"Removed reviewer hook and restored original backup hook."
        return True, "Pre-commit hook successfully removed."
    return False, "No pre-commit hook was found."
